/** The filter as a link: what the address bar says, and what a link means. */
class CustomerFilterUrlTest {

    @Test
    void theFilterReadsBackAsTheAddressBarWroteIt() {
        assertEquals("", urlOf(CustomerFilter.EMPTY));
        assertEquals("?name=vir", urlOf(CustomerFilter.byName("vir")));
        assertEquals("?status=ACTIVE,CLOSED",
                urlOf(CustomerFilter.byStatus(CustomerStatus.CLOSED, CustomerStatus.ACTIVE)));
        assertEquals("?name=vir&status=ACTIVE,CLOSED",
                urlOf(new CustomerFilter("vir",
                        Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED))));
        assertEquals("?name=ada%20aal", urlOf(CustomerFilter.byName("ada aal")));
    }

    @Test
    void aLinkMeansTheFilterItShows() {
        assertEquals(CustomerFilter.EMPTY, parse(Map.of()));
        assertEquals(CustomerFilter.byName("vir"), parse(Map.of("name", "vir")));
        assertEquals(new CustomerFilter("vir", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED)),
                parse(Map.of("name", "vir", "status", "ACTIVE,CLOSED")));
    }

    @Test
    void aHandEditedLinkIsReadAsFarAsItMakesSense() {
        assertEquals(CustomerFilter.byStatus(CustomerStatus.ACTIVE),
                parse(Map.of("status", "active , BOGUS")));
        assertEquals(CustomerFilter.EMPTY, parse(Map.of("status", "")));
    }

    @Test
    void everyFilterSurvivesTheRoundTrip() {
        CustomerFilter filter = new CustomerFilter("ada aal",
                Set.of(CustomerStatus.ACTIVE, CustomerStatus.PENDING));
        Location location = new Location("", CustomerFilterUrl.toQueryParameters(filter));

        assertEquals(filter, CustomerFilterUrl.parse(
                new Location(location.getPathWithQueryParameters()).getQueryParameters()));
    }

    private static String urlOf(CustomerFilter filter) {
        return new Location("", CustomerFilterUrl.toQueryParameters(filter))
                .getPathWithQueryParameters();
    }

    private static CustomerFilter parse(Map<String, String> parameters) {
        return CustomerFilterUrl.parse(QueryParameters.simple(parameters));
    }
