@@ -0,0 +1,115 @@
+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * What the customer list is narrowed down to: some name text and a set of
+ * statuses. Both halves are optional, and an empty filter matches every
+ * customer.
+ *
+ * <p>The name text is split on whitespace into terms, and a customer matches
+ * only when <em>every</em> term appears in its first or last name. Comparison
+ * ignores case and accents on both sides, so {@code makinen}, {@code MAKINEN}
+ * and {@code mäkinen} all match {@code Mäkinen}.
+ *
+ * <p>Statuses widen nothing: with none selected every status is shown, with one
+ * or more selected only those are.
+ *
+ * <p>{@link CustomerRepository} applies this in the backend, one page at a time,
+ * so a filtered list costs the same as an unfiltered one.
+ *
+ * @param name     the name text as the user entered it, trimmed
+ * @param statuses the statuses to show, in {@link CustomerStatus} declaration
+ *                 order; empty means all of them
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter(String name, Set<CustomerStatus> statuses) {
+        this.name = (name == null) ? "" : name.trim();
+        this.statuses = Collections.unmodifiableSet(toEnumSet(statuses));
+    }
+
+    /** A filter on the name only. */
+    public static CustomerFilter byName(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    /** A filter on the statuses only. */
+    public static CustomerFilter byStatus(CustomerStatus... statuses) {
+        return new CustomerFilter("", Set.of(statuses));
+    }
+
+    /** Whether this filter narrows nothing down. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The name text split into the terms a customer has to match, all of them. */
+    public List<String> nameTerms() {
+        if (name.isEmpty()) {
+            return List.of();
+        }
+        return Arrays.stream(WHITESPACE.split(name))
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::normalize)
+                .toList();
+    }
+
+    /**
+     * Returns a predicate matching exactly the customers this filter shows.
+     *
+     * <p>The terms are normalized once here, not once per customer.
+     */
+    public Predicate<Customer> asPredicate() {
+        if (isEmpty()) {
+            return customer -> true;
+        }
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> allowed = statuses;
+        return customer -> matchesStatus(customer, allowed) && matchesName(customer, terms);
+    }
+
+    private static boolean matchesStatus(Customer customer, Set<CustomerStatus> allowed) {
+        return allowed.isEmpty() || allowed.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /**
+     * The case- and accent-insensitive form used on both sides of a comparison:
+     * decompose, drop the combining marks, lower-case.
+     */
+    public static String normalize(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+
+    private static EnumSet<CustomerStatus> toEnumSet(Set<CustomerStatus> statuses) {
+        EnumSet<CustomerStatus> result = EnumSet.noneOf(CustomerStatus.class);
+        if (statuses != null) {
+            result.addAll(statuses);
+        }
+        return result;
+    }
+}
