+package com.example.customers.ui;
+
+import java.io.Serializable;
+import java.net.URLEncoder;
+import java.nio.charset.StandardCharsets;
+import java.util.ArrayList;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.LinkedHashMap;
+import java.util.List;
+import java.util.Locale;
+import java.util.Map;
+import java.util.Optional;
+import java.util.Set;
+import java.util.stream.Collectors;
+
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerStatus;
+
+import com.vaadin.flow.router.QueryParameters;
+
+/**
+ * Carries a {@link CustomerFilter} in the view's URL, as {@code ?name=…} and
+ * {@code ?status=…}, where {@code status} is a comma-separated list of status
+ * names — for example {@code /?name=vir&status=ACTIVE,CLOSED}.
+ */
+final class CustomerFilterUrl {
+
+    static final String NAME_PARAMETER = "name";
+    static final String STATUS_PARAMETER = "status";
+
+    private CustomerFilterUrl() {
+    }
+
+    /**
+     * Reads a filter from query parameters. Anything unrecognized is ignored, so
+     * a hand-edited URL narrows the list down as far as it makes sense and no
+     * further.
+     */
+    static CustomerFilter parse(QueryParameters parameters) {
+        String name = parameters.getParameters(NAME_PARAMETER).stream()
+                .findFirst().orElse("");
+        Set<CustomerStatus> statuses = EnumSet.noneOf(CustomerStatus.class);
+        parameters.getParameters(STATUS_PARAMETER).stream()
+                .flatMap(value -> Arrays.stream(value.split(",")))
+                .map(CustomerFilterUrl::statusFor)
+                .forEach(status -> status.ifPresent(statuses::add));
+        return new CustomerFilter(name, statuses);
+    }
+
+    /**
+     * Writes a filter as query parameters. An empty filter yields no parameters
+     * at all, so a cleared filter leaves nothing behind in the URL.
+     */
+    static QueryParameters toQueryParameters(CustomerFilter filter) {
+        Map<String, List<String>> parameters = new LinkedHashMap<>();
+        if (!filter.name().isEmpty()) {
+            parameters.put(NAME_PARAMETER, List.of(filter.name()));
+        }
+        if (!filter.statuses().isEmpty()) {
+            parameters.put(STATUS_PARAMETER, List.of(filter.statuses().stream()
+                    .map(CustomerStatus::name)
+                    .collect(Collectors.joining(","))));
+        }
+        return new FilterQueryParameters(parameters, queryStringFor(parameters));
+    }
+
+    /** The query string as it should read in the address bar. */
+    static String queryStringFor(Map<String, List<String>> parameters) {
+        List<String> parts = new ArrayList<>();
+        parameters.forEach((parameter, values) -> values
+                .forEach(value -> parts.add(parameter + "=" + encode(value))));
+        return String.join("&", parts);
+    }
+
+    private static Optional<CustomerStatus> statusFor(String value) {
+        String name = value.trim().toUpperCase(Locale.ROOT);
+        return Arrays.stream(CustomerStatus.values())
+                .filter(status -> status.name().equals(name))
+                .findFirst();
+    }
+
+    /**
+     * Percent-encodes a parameter value the way a browser address bar shows it,
+     * but leaves the comma separating statuses alone: a comma is legal in a
+     * query string, and {@code status=ACTIVE,CLOSED} is what a colleague reading
+     * the link should see.
+     */
+    private static String encode(String value) {
+        return URLEncoder.encode(value, StandardCharsets.UTF_8)
+                .replace("+", "%20")
+                .replace("%2C", ",");
+    }
+
+    /**
+     * Query parameters that render as {@link #queryStringFor(Map)} instead of
+     * Flow's default encoding, so the URL keeps the parameter order and the
+     * comma of the documented form.
+     */
+    private static final class FilterQueryParameters extends QueryParameters
+            implements Serializable {
+
+        private final String queryString;
+
+        private FilterQueryParameters(Map<String, List<String>> parameters, String queryString) {
+            super(parameters);
+            this.queryString = queryString;
+        }
+
+        @Override
+        public String getQueryString() {
+            return queryString;
+        }
+    }
+}
