+        UI.getCurrent().navigate("", QueryParameters.simple(queryParameters));
+    }
+
+    private void type(String text) {
+        test(nameFilter()).setValue(text);
+    }
+
+    private void select(CustomerStatus... statuses) {
+        statusFilter().setValue(Set.of(statuses));
+    }
+
+    private Grid<?> grid() {
+        return find(Grid.class).single();
+    }
+
+    private TextField nameFilter() {
+        return find(TextField.class).withPlaceholder("Filter by name").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private MultiSelectComboBox<CustomerStatus> statusFilter() {
+        return find(MultiSelectComboBox.class).withLabel("Status").single();
+    }
+
+    private Span summary() {
+        return find(Span.class).withTextContaining("Showing").single();
+    }
 }
diff --git a/src/test/java/com/example/customers/domain/CustomerFilterTest.java b/src/test/java/com/example/customers/domain/CustomerFilterTest.java
new file mode 100644
index 0000000..d1ff3ab
--- /dev/null
+++ b/src/test/java/com/example/customers/domain/CustomerFilterTest.java
@@ -0,0 +1,81 @@
+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+/** What the filter considers a match, without a UI or a repository in the way. */
+class CustomerFilterTest {
+
+    private static final Customer ADA =
+            new Customer(1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer DAGNY =
+            new Customer(2, "Dagny", "Mäkinen", "dagny@example.com", "Finland", CustomerStatus.PENDING);
+    private static final Customer JOSEPHINE =
+            new Customer(3, "Joséphine", "Engberg", "jose@example.com", "France", CustomerStatus.CLOSED);
+
+    @Test
+    void anEmptyFilterMatchesEveryone() {
+        assertTrue(CustomerFilter.EMPTY.isEmpty());
+        assertTrue(matches(CustomerFilter.EMPTY, ADA));
+        assertTrue(matches(new CustomerFilter("   ", Set.of()), ADA));
+    }
+
+    @Test
+    void everyTermHasToMatchTheFirstOrTheLastName() {
+        assertTrue(matches(CustomerFilter.byName("ada aal"), ADA));
+        assertTrue(matches(CustomerFilter.byName("aal ada"), ADA));
+        assertTrue(matches(CustomerFilter.byName("  ada   aal  "), ADA));
+        assertFalse(matches(CustomerFilter.byName("ada virtanen"), ADA));
+    }
+
+    @Test
+    void matchingIgnoresCaseAndAccentsBothWays() {
+        assertTrue(matches(CustomerFilter.byName("makinen"), DAGNY));
+        assertTrue(matches(CustomerFilter.byName("MAKINEN"), DAGNY));
+        assertTrue(matches(CustomerFilter.byName("mäkinen"), DAGNY));
+        assertTrue(matches(CustomerFilter.byName("josephine"), JOSEPHINE));
+        assertTrue(matches(CustomerFilter.byName("Joséphine"), JOSEPHINE));
+    }
+
+    @Test
+    void statusesNarrowDownAndNoneMeansAll() {
+        assertTrue(matches(CustomerFilter.byStatus(), DAGNY));
+        assertTrue(matches(CustomerFilter.byStatus(CustomerStatus.PENDING), DAGNY));
+        assertFalse(matches(CustomerFilter.byStatus(CustomerStatus.ACTIVE), DAGNY));
+        assertTrue(matches(
+                CustomerFilter.byStatus(CustomerStatus.ACTIVE, CustomerStatus.PENDING), DAGNY));
+    }
+
+    @Test
+    void bothHalvesHaveToMatch() {
+        CustomerFilter filter = new CustomerFilter("mak", Set.of(CustomerStatus.ACTIVE));
+        assertFalse(matches(filter, DAGNY), "the name matches but the status does not");
+        assertFalse(matches(filter, ADA), "the status matches but the name does not");
+    }
+
+    @Test
+    void statusesAreKeptInDeclarationOrder() {
+        CustomerFilter filter = new CustomerFilter("",
+                new java.util.LinkedHashSet<>(
+                        List.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE)));
+        assertEquals(List.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED),
+                List.copyOf(filter.statuses()));
+    }
+
+    @Test
+    void theSameFilterEnteredTwoWaysIsTheSameFilter() {
+        assertEquals(new CustomerFilter("vir", Set.of(CustomerStatus.ACTIVE)),
+                new CustomerFilter(" vir ", Set.of(CustomerStatus.ACTIVE)));
+        assertEquals(CustomerFilter.EMPTY, new CustomerFilter(null, null));
+    }
+
+    private static boolean matches(CustomerFilter filter, Customer customer) {
+        return filter.asPredicate().test(customer);
+    }
+}
